// Imported as a macro, so this runs when the CLI is bundled: the compiled
// binary carries the files the core stack needs as one inlined object
import { Glob } from 'bun'
import { readFileSync } from 'fs'
import { join, resolve } from 'path'

// The repo root: the core stack lives beside apps/
const CHECKOUT = resolve(import.meta.dir, '../../../..')
const PATTERNS = ['compose.yaml', 'services/**/*']
// Generated by `local-env setup`, never shipped
const EXCLUDED = /^services\/proxy\/certs\//

// Text as is; other files (the dashboard's fonts) as base64, which survives
// being inlined as a string
export type ShippedFile = string | { base64: string }

const utf8 = new TextDecoder('utf-8', { fatal: true })

export const readShippedFile = (path: string): ShippedFile => {
  const bytes = readFileSync(path)
  try {
    return utf8.decode(bytes)
  } catch {
    return { base64: bytes.toString('base64') }
  }
}

export const readShippedFiles = () => {
  const files: Record<string, ShippedFile> = {}
  for (const pattern of PATTERNS) {
    for (const path of new Glob(pattern).scanSync({ cwd: CHECKOUT })) {
      if (EXCLUDED.test(path)) continue
      files[path] = readShippedFile(join(CHECKOUT, path))
    }
  }
  // Sorted so the content hash doesn't depend on the scan order
  return Object.fromEntries(
    Object.entries(files).sort(([a], [b]) => a.localeCompare(b)),
  )
}
